package com.cbs.payments;

import static com.cbs.payments.StatementImportModels.*;
import com.cbs.access.AccessService;
import com.cbs.accounting.*;
import com.cbs.reference.ReferenceDataService;
import com.cbs.tenancy.*;
import com.cbs.tenancy.TenantModels.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.json.JsonMapper;

@Service
@ConditionalOnProperty(name="cbs.tenancy.enabled",havingValue="true",matchIfMissing=true)
public class StatementImportService {
 private static final JsonMapper JSON=JsonMapper.builder().build();
 public record Row(UUID id,Line source,String status,UUID paymentId,UUID decisionId,String decisionKind,UUID relatedId,UUID journalId) {}
 public record Report(UUID id,String status,Source source,List<Row> rows,Map<String,String> balances,List<String> unmatchedCbs,List<UUID> missingPayments,List<UUID> conflicts,List<String> blockers,String reportHash) {}
 private final PaymentReturnService returns;
 private final JdbcTemplate jdbc;private final TenantRepository tenants;private final AccountingReportService reports;
 private final JournalService journals;private final PaymentService payments;private final ReferenceDataService reference;private final TransactionTemplate tx;
 public StatementImportService(PaymentReturnService returns,JdbcTemplate jdbc,TenantRepository tenants,AccountingReportService reports,JournalService journals,PaymentService payments,ReferenceDataService reference,PlatformTransactionManager manager){this.returns=returns;this.jdbc=jdbc;this.tenants=tenants;this.reports=reports;this.journals=journals;this.payments=payments;this.reference=reference;this.tx=new TransactionTemplate(manager);}
 private static BigDecimal money(String s){return MpesaStatementCsv.money(s);}
 private static String text(BigDecimal n){return MpesaStatementCsv.text(n);}
 private static String hash(Object value){return PaymentService.hash(JSON.writeValueAsString(value));}
 private Map<String,Object> batch(Actor actor,UUID bank,UUID id){var rows=jdbc.queryForList("SELECT * FROM platform.statement_import WHERE tenant_id=? AND id=? AND issuer=?",bank,id,actor.issuer());if(rows.isEmpty())throw error("STATEMENT_NOT_FOUND");return rows.getFirst();}
 private Source source(Map<String,Object> batch){return JSON.readValue(batch.get("source").toString(),Source.class);}
 private Map<String,Object> ledger(UUID bank,UUID id){var rows=jdbc.queryForList("SELECT l.*,c.category,c.normal_balance FROM platform.ledger_registry l JOIN platform.chart_account c ON c.id=l.chart_account_id WHERE l.tenant_id=? AND l.id=? AND l.active AND l.delivery='APPLIED' AND c.active AND c.kind='POSTING'",bank,id);if(rows.isEmpty())throw error("STATEMENT_LEDGER_INVALID");return rows.getFirst();}
 private void wallet(UUID bank,UUID id){var l=ledger(bank,id);if(!"KES".equals(l.get("currency"))||!"ASSET".equals(l.get("category"))||!"DEBIT".equals(l.get("normal_balance")))throw error("STATEMENT_LEDGER_INVALID");if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.account_ledger WHERE ledger_id=?) OR EXISTS(SELECT 1 FROM platform.cash_location WHERE ledger_id=?) OR EXISTS(SELECT 1 FROM platform.cash_transit WHERE ledger_id=?)",Boolean.class,id,id,id))throw error("STATEMENT_LEDGER_INVALID");}
 private static String identity(Line line){return hash(List.of(line.receipt(),line.date(),line.type(),line.credit(),line.debit(),line.paymentReference(),line.beneficiary()));}
 public Map<String,Object> preview(Actor actor,UUID bank,Upload input){PaymentAccess.require(jdbc,actor,bank,PaymentAccess.Capability.MAKE);return tx.execute(t->{var tenant=tenants.get(bank,true);wallet(bank,input.ledgerId());var lines=MpesaStatementCsv.parse(input,PaymentService.latestSettlementDate(reference.read(tenant)));return Map.of("rows",lines.size(),"openingBalance",text(money(input.openingBalance())),"closingBalance",text(money(input.closingBalance())),"credits",text(lines.stream().map(l->money(l.credit())).reduce(BigDecimal.ZERO,BigDecimal::add)),"debits",text(lines.stream().map(l->money(l.debit())).reduce(BigDecimal.ZERO,BigDecimal::add)),"sample",lines.stream().limit(10).toList());});}
 public UUID upload(Actor actor,UUID bankId,UUID key,Upload input){PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);var lines=MpesaStatementCsv.parse(input,PaymentService.latestSettlementDate(reference.read(tenants.get(bankId,false))));return tx.execute(t->{
  jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",r->{},actor.issuer()+":"+actor.subject()+":"+key);var bank=tenants.get(bankId,true);PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.MAKE);String requestHash=hash(input);
  var commands=jdbc.queryForList("SELECT * FROM platform.statement_import_command WHERE issuer=? AND subject=? AND idempotency_key=?",actor.issuer(),actor.subject(),key);if(!commands.isEmpty()){var old=commands.getFirst();if(!bankId.equals(old.get("tenant_id"))||!requestHash.equals(old.get("request_hash")))throw error("IDEMPOTENCY_CONFLICT");return (UUID)old.get("batch_id");}
  wallet(bankId,input.ledgerId());if(bank.version()!=input.expectedVersion())throw error("STALE_VERSION");
  var document=new Source(input.ledgerId(),input.statementReference(),input.walletReference(),input.fromDate(),input.toDate(),text(money(input.openingBalance())),text(money(input.closingBalance())),input.evidenceReference(),PaymentService.hash(input.csv()),new TreeMap<>(input.columns()));
  String fingerprint=hash(List.of(input.ledgerId(),input.fromDate(),input.toDate(),document.openingBalance(),document.closingBalance(),lines));
  var identical=jdbc.queryForList("SELECT id FROM platform.statement_import WHERE tenant_id=? AND ledger_id=? AND fingerprint=?",UUID.class,bankId,input.ledgerId(),fingerprint);
  UUID id;if(!identical.isEmpty())id=identical.getFirst();else{
   if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_import WHERE tenant_id=? AND ledger_id=? AND reference=?)",Boolean.class,bankId,input.ledgerId(),input.statementReference()))throw error("STATEMENT_REFERENCE_USED");
   id=UUID.randomUUID();jdbc.update("INSERT INTO platform.statement_import(id,tenant_id,ledger_id,issuer,importer,reference,source,fingerprint) VALUES (?,?,?,?,?,?,?::jsonb,?)",id,bankId,input.ledgerId(),actor.issuer(),actor.subject(),input.statementReference(),JSON.writeValueAsString(document),fingerprint);
   for(var line:lines)jdbc.update("INSERT INTO platform.statement_line(id,tenant_id,batch_id,line_number,source,identity_hash) VALUES (?,?,?,?,?::jsonb,?)",UUID.randomUUID(),bankId,id,line.number(),JSON.writeValueAsString(line),identity(line));changed(actor,bank,"STATEMENT_IMPORTED",id);
  }
  jdbc.update("INSERT INTO platform.statement_import_command VALUES (?,?,?,?,?,?)",actor.issuer(),actor.subject(),key,bankId,id,requestHash);return id;
 });}
 public Map<String,Object> list(Actor actor,UUID bank,int limit,int offset){PaymentAccess.require(jdbc,actor,bank,PaymentAccess.Capability.READ);AccessService.page(limit,offset);return tx.execute(t->{var tenant=tenants.get(bank,true);return Map.of("version",tenant.version(),"items",jdbc.query("SELECT id,source,status,created_at FROM platform.statement_import WHERE tenant_id=? AND issuer=? ORDER BY created_at DESC,id LIMIT ? OFFSET ?",(r,n)->Map.of("id",r.getObject(1),"source",JSON.readValue(r.getString(2),Source.class),"status",r.getString(3),"createdAt",r.getTimestamp(4).toInstant()),bank,actor.issuer(),limit,offset),"total",jdbc.queryForObject("SELECT count(*) FROM platform.statement_import WHERE tenant_id=? AND issuer=?",Long.class,bank,actor.issuer()));});}
 public Map<String,Object> detail(Actor actor,UUID bank,int limit,int offset,UUID id,boolean exceptions){PaymentAccess.require(jdbc,actor,bank,PaymentAccess.Capability.READ);AccessService.page(limit,offset);return tx.execute(t->{var tenant=tenants.get(bank,true);var report=report(actor,tenant,id);var filtered=report.rows().stream().filter(r->!exceptions||!r.status().equals("RESOLVED")).toList();var result=new LinkedHashMap<String,Object>();result.put("version",tenant.version());result.put("id",id);result.put("status",report.status());result.put("source",report.source());result.put("rows",filtered.stream().skip(offset).limit(limit).toList());result.put("total",filtered.size());result.put("balances",report.balances());result.put("unmatchedCbs",report.unmatchedCbs());result.put("missingPayments",report.missingPayments());result.put("conflicts",report.conflicts());result.put("blockers",report.blockers());result.put("reportHash",report.reportHash());result.put("history",jdbc.query("SELECT kind,subject,payload,created_at FROM platform.statement_decision WHERE batch_id=? ORDER BY created_at DESC,id LIMIT 100",(r,n)->Map.of("kind",r.getString(1),"subject",r.getString(2),"action",JSON.readTree(r.getString(3)).path("action"),"at",r.getTimestamp(4).toInstant()),id));tenants.audit(actor,bank,"STATEMENT_VIEWED",tenant.version(),tenant.status(),tenant.status(),"Statement reconciliation viewed",null,null,Map.of("batchId",id));return result;});}
 private List<Map<String,Object>> paymentRows(Actor actor,UUID bank,UUID ledger){var rows=jdbc.queryForList("SELECT p.*,o.completed FROM platform.payment_order p JOIN platform.account_operation o ON o.request_id=p.id WHERE p.tenant_id=? AND p.issuer=? AND p.payload->>'settlementLedgerId'=? ORDER BY p.id LIMIT 10001",bank,actor.issuer(),ledger.toString());if(rows.size()>10000)throw error("STATEMENT_REPORT_TOO_LARGE");return rows;}
 private PaymentModels.Order paymentOrder(Map<String,Object> row){return JSON.readValue(row.get("payload").toString(),PaymentModels.Order.class);}
 private boolean fits(Line line,Map<String,Object> row){var p=paymentOrder(row);return money(line.debit()).compareTo(new BigDecimal(p.amount()))==0&&line.credit().equals("0")&&line.beneficiary().equals(p.beneficiary())&&line.paymentReference().equals(p.reference())&&!line.date().isBefore(p.businessDate());}
 private Report report(Actor actor,Tenant bank,UUID id){
  var batch=batch(actor,bank.id(),id);var source=source(batch);var asset=jdbc.queryForMap("SELECT * FROM platform.ledger_registry WHERE tenant_id=? AND id=?",bank.id(),source.ledgerId());
  var gl=reports.generateForReconciliation(actor,bank.id(),AccountingReportService.Kind.LEDGER_STATEMENT,(UUID)asset.get("legal_entity_id"),"KES",source.fromDate(),source.toDate(),source.ledgerId(),jdbc);
  var paymentRows=paymentRows(actor,bank.id(),source.ledgerId());var byPayment=new HashMap<UUID,Map<String,Object>>();var byRef=new HashMap<String,List<Map<String,Object>>>();for(var p:paymentRows){byPayment.put((UUID)p.get("id"),p);byRef.computeIfAbsent(paymentOrder(p).reference(),k->new ArrayList<>()).add(p);}
  var raw=jdbc.queryForList("SELECT l.*,d.kind,d.related_id,d.journal_id,j.completed FROM platform.statement_line l LEFT JOIN platform.statement_decision d ON d.id=l.decision_id LEFT JOIN platform.journal_delivery j ON j.request_id=d.journal_id WHERE l.batch_id=? ORDER BY l.line_number",id);
  var reversed=new HashSet<>(jdbc.queryForList("SELECT reversal_of FROM platform.journal_delivery WHERE tenant_id=? AND reversal_of IS NOT NULL",UUID.class,bank.id()));
  var covered=new HashSet<String>();var matchedPayments=new HashSet<UUID>();var rows=new ArrayList<Row>();var conflicts=new ArrayList<UUID>();var missing=new ArrayList<UUID>();
  // All posted correction/reversal history remains attributed to its source row.
  covered.addAll(jdbc.queryForList("SELECT d.journal_id::text FROM platform.statement_decision d JOIN platform.journal_delivery j ON j.request_id=d.journal_id WHERE d.batch_id=? AND j.completed AND d.kind IN ('BOOK','REVERSE')",String.class,id));
  var closedDuplicates=jdbc.queryForList("SELECT l.id,l.identity_hash,l.batch_id FROM platform.statement_line l JOIN platform.statement_import b ON b.id=l.batch_id WHERE b.tenant_id=? AND b.ledger_id=? AND b.status='CLOSED' AND EXISTS(SELECT 1 FROM platform.statement_decision d WHERE d.id=l.decision_id AND d.kind<>'DUPLICATE') AND b.id<>? AND l.identity_hash IN (SELECT identity_hash FROM platform.statement_line WHERE batch_id=?) LIMIT 10001",bank.id(),source.ledgerId(),id,id);if(closedDuplicates.size()>10000)throw error("STATEMENT_REPORT_TOO_LARGE");
  for(var r:raw){var line=JSON.readValue(r.get("source").toString(),Line.class);UUID lineId=(UUID)r.get("id"),decision=(UUID)r.get("decision_id"),related=(UUID)r.get("related_id"),journal=(UUID)r.get("journal_id");String kind=(String)r.get("kind"),status="NEEDS_LEDGER";UUID paymentId=null;
   var candidates=byRef.getOrDefault(line.paymentReference(),List.of());if(line.type()==Type.PAYOUT){if(kind!=null&&kind.equals("MATCH")&&related!=null&&byPayment.containsKey(related))candidates=List.of(byPayment.get(related));
    if(candidates.size()!=1)status=candidates.isEmpty()?"UNMATCHED_EXTERNAL":"AMBIGUOUS_PAYMENT";else{var p=candidates.getFirst();paymentId=(UUID)p.get("id");status=!fits(line,p)?"PAYMENT_MISMATCH":Boolean.TRUE.equals(p.get("reconciliation_conflict"))?"PAYMENT_CONFLICT":!Boolean.TRUE.equals(p.get("completed"))?"POSTING_PENDING":List.of("SUBMITTED","UNKNOWN","SETTLED","RETURN_PENDING","RETURNED").contains(p.get("state"))?"READY_MATCH":"PAYMENT_STATE_CONFLICT";}
   }
   if(decision!=null){
    if(kind.equals("MATCH")){var p=byPayment.get(related);if(p!=null&&fits(line,p)&&List.of("SETTLED","RETURN_PENDING","RETURNED").contains(p.get("state"))&&!Boolean.TRUE.equals(p.get("reconciliation_conflict"))&&receiptMatches(bank.id(),related,line.receipt())){status="RESOLVED";paymentId=related;covered.add(related.toString());matchedPayments.add(related);}else status="PAYMENT_CONFLICT";}
    else if(kind.equals("BOOK")||kind.equals("LINK")||kind.equals("RETURN")){status=reversed.contains(journal)?"JOURNAL_REVERSED":Boolean.TRUE.equals(r.get("completed"))?"RESOLVED":"POSTING_PENDING";if(status.equals("RESOLVED"))covered.add(journal.toString());}
    else if(kind.equals("UNLINK"))status="NEEDS_LEDGER";
    else if(kind.equals("REVERSE"))status=Boolean.TRUE.equals(r.get("completed"))?"NEEDS_LEDGER":"POSTING_PENDING";
    else if(kind.equals("DUPLICATE")){UUID priorId=related;var prior=closedDuplicates.stream().filter(v->v.get("id").equals(priorId)&&v.get("identity_hash").equals(r.get("identity_hash"))).findFirst();if(prior.isPresent()){status="RESOLVED";covered.addAll(jdbc.queryForList("SELECT d.journal_id::text FROM platform.statement_decision d JOIN platform.journal_delivery j ON j.request_id=d.journal_id WHERE d.line_id=? AND j.completed AND (d.kind IN ('BOOK','REVERSE') OR d.id=(SELECT decision_id FROM platform.statement_line WHERE id=d.line_id))",String.class,related));if(paymentId!=null){covered.add(paymentId.toString());matchedPayments.add(paymentId);}}else status="DUPLICATE_REVIEW_REQUIRED";}
   }else if(!closedDuplicates.stream().filter(v->v.get("identity_hash").equals(r.get("identity_hash"))).toList().isEmpty()){status="DUPLICATE_REVIEW_REQUIRED";related=(UUID)closedDuplicates.stream().filter(v->v.get("identity_hash").equals(r.get("identity_hash"))).findFirst().orElseThrow().get("id");}
   rows.add(new Row(lineId,line,status,paymentId,decision,kind,related,journal));
  }
  var carries=jdbc.queryForList("SELECT c.id,c.payment_id,c.effective_from,c.resolved_date,p.payload->>'amount' AS amount FROM platform.payment_case c JOIN platform.payment_order p ON p.id=c.payment_id WHERE c.tenant_id=? AND c.kind='SETTLEMENT_DELAY' AND c.effective_from IS NOT NULL AND c.state<>'CANCELLED' AND p.payload->>'settlementLedgerId'=? ORDER BY c.id",bank.id(),source.ledgerId().toString());
  BigDecimal openingCarry=BigDecimal.ZERO,closingCarry=BigDecimal.ZERO;var carriedPayments=new HashSet<UUID>();var carryIds=new ArrayList<String>();
  for(var c:carries){var start=((java.sql.Date)c.get("effective_from")).toLocalDate();var end=c.get("resolved_date")==null?null:((java.sql.Date)c.get("resolved_date")).toLocalDate();var amount=new BigDecimal(c.get("amount").toString()).negate();boolean atStart=start.isBefore(source.fromDate())&&(end==null||!end.isBefore(source.fromDate()));boolean atEnd=!start.isAfter(source.toDate())&&(end==null||end.isAfter(source.toDate()));if(atStart)openingCarry=openingCarry.add(amount);if(atEnd){closingCarry=closingCarry.add(amount);carriedPayments.add((UUID)c.get("payment_id"));covered.add(c.get("payment_id").toString());}if(atStart||atEnd)carryIds.add(c.get("id").toString());}
  for(var p:paymentRows){var order=paymentOrder(p);if(order.businessDate().isBefore(source.fromDate())||order.businessDate().isAfter(source.toDate()))continue;UUID payment=(UUID)p.get("id");if(Boolean.TRUE.equals(p.get("reconciliation_conflict")))conflicts.add(payment);
   if(p.get("state").equals("REFUNDED")){covered.add(payment.toString());if(p.get("refund_id")!=null)covered.add(p.get("refund_id").toString());}
   else if(!matchedPayments.contains(payment)&&!carriedPayments.contains(payment))missing.add(payment);
  }
  var unmatched=gl.rows().stream().map(r->r.get(3)).distinct().filter(j->!covered.contains(j)).sorted().toList();
  int pending=jdbc.queryForObject("SELECT count(DISTINCT j.request_id) FROM platform.journal_delivery j JOIN platform.journal_ledger l ON l.request_id=j.request_id WHERE j.tenant_id=? AND l.ledger_id=? AND NOT j.completed",Integer.class,bank.id(),source.ledgerId());
  var balance=new TreeMap<String,String>();balance.put("providerOpening",source.openingBalance());balance.put("providerClosing",source.closingBalance());balance.put("cbsOpening",gl.summary().get("Opening net debit"));balance.put("cbsClosing",gl.summary().get("Closing net debit"));balance.put("openingDifference",text(new BigDecimal(balance.get("cbsOpening")).subtract(money(source.openingBalance()))));balance.put("closingDifference",text(new BigDecimal(balance.get("cbsClosing")).subtract(money(source.closingBalance()))));balance.put("fees",text(rows.stream().filter(r->r.source().type()==Type.FEE).map(r->money(r.source().debit())).reduce(BigDecimal.ZERO,BigDecimal::add)));balance.put("pendingAccounting",Integer.toString(pending));
  balance.put("openingCarry",text(openingCarry));balance.put("closingCarry",text(closingCarry));balance.put("unexplainedOpening",text(new BigDecimal(balance.get("openingDifference")).subtract(openingCarry)));balance.put("unexplainedClosing",text(new BigDecimal(balance.get("closingDifference")).subtract(closingCarry)));balance.put("carryCaseIds",String.join(",",carryIds));
  var blockers=new ArrayList<String>();if(rows.stream().anyMatch(r->!r.status().equals("RESOLVED")))blockers.add("UNRESOLVED_ROWS");if(!balance.get("unexplainedOpening").equals("0"))blockers.add("OPENING_DIFFERENCE");if(!balance.get("unexplainedClosing").equals("0"))blockers.add("CLOSING_DIFFERENCE");if(!unmatched.isEmpty())blockers.add("UNMATCHED_CBS");if(!missing.isEmpty())blockers.add("MISSING_PROVIDER");if(!conflicts.isEmpty())blockers.add("PAYMENT_CONFLICT");if(pending>0)blockers.add("PENDING_ACCOUNTING");
  var result=new Report(id,batch.get("status").toString(),source,List.copyOf(rows),balance,unmatched,List.copyOf(missing),List.copyOf(conflicts),List.copyOf(blockers),"");return new Report(result.id(),result.status(),source,result.rows(),balance,unmatched,result.missingPayments(),result.conflicts(),result.blockers(),hash(result));
 }
 private boolean receiptMatches(UUID bank,UUID payment,String receipt){return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.payment_resolution WHERE tenant_id=? AND payment_id=? AND outcome='MATCH' AND lower(provider_reference)=lower(?))",Boolean.class,bank,payment,receipt);}
 private Row selected(Report report,UUID line){return report.rows().stream().filter(r->r.id().equals(line)).findFirst().orElseThrow(()->error("STATEMENT_LINE_NOT_FOUND"));}
 private Map<String,Object> payment(Actor actor,UUID bank,UUID id){var rows=jdbc.queryForList("SELECT * FROM platform.payment_order WHERE tenant_id=? AND issuer=? AND id=?",bank,actor.issuer(),id);if(rows.isEmpty())throw error("PAYMENT_NOT_FOUND");return rows.getFirst();}
 private UUID candidate(Row row,Action action){return action.relatedId()==null?row.paymentId():action.relatedId();}
 public Report validate(Actor actor,Tenant bank,Action input){
  PaymentAccess.require(jdbc,actor,bank.id(),PaymentAccess.Capability.READ);
  boolean lineAction=List.of(Kind.MATCH,Kind.RETURN,Kind.LINK,Kind.UNLINK,Kind.BOOK,Kind.REVERSE,Kind.DUPLICATE).contains(input.kind());
  if(lineAction!=(input.lineId()!=null)||(!List.of(Kind.MATCH,Kind.UNLINK,Kind.REVERSE,Kind.CLOSE,Kind.REOPEN).contains(input.kind())&&input.relatedId()==null)||(List.of(Kind.UNLINK,Kind.REVERSE,Kind.CLOSE,Kind.REOPEN).contains(input.kind())&&input.relatedId()!=null))throw error("STATEMENT_ACTION_INVALID");
  if(bank.version()!=input.expectedVersion())throw error("STALE_VERSION");var result=report(actor,bank,input.batchId());if(!result.reportHash().equals(input.reportHash()))throw error("STATEMENT_REPORT_CHANGED");
  if(input.kind()==Kind.REOPEN){if(!result.status().equals("CLOSED"))throw error("STATEMENT_STATE_INVALID");if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_decision d JOIN platform.statement_line l ON l.id=d.related_id JOIN platform.statement_import b ON b.id=d.batch_id WHERE d.kind='DUPLICATE' AND l.batch_id=? AND b.status='CLOSED')",Boolean.class,input.batchId()))throw error("STATEMENT_DEPENDENTS_CLOSED");return result;}
  if(!result.status().equals("OPEN"))throw error("STATEMENT_STATE_INVALID");
  if(input.kind()==Kind.CLOSE){if(!result.blockers().isEmpty())throw error("STATEMENT_NOT_RECONCILED");return result;}
  if(input.kind()==Kind.SUPERSEDE){var replacement=batch(actor,bank.id(),input.relatedId());var next=source(replacement);if(input.batchId().equals(input.relatedId())||replacement.get("status").equals("SUPERSEDED")||!next.ledgerId().equals(result.source().ledgerId())||!next.fromDate().equals(result.source().fromDate())||!next.toDate().equals(result.source().toDate()))throw error("STATEMENT_REPLACEMENT_INVALID");if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_decision WHERE batch_id=?)",Boolean.class,input.batchId()))throw error("STATEMENT_HAS_DECISIONS");return result;}
  if(input.kind()==Kind.CLEAR_CONFLICT){
   var p=payment(actor,bank.id(),input.relatedId());var order=paymentOrder(p);if(!Boolean.TRUE.equals(p.get("reconciliation_conflict"))||!order.settlementLedgerId().equals(result.source().ledgerId())||order.businessDate().isAfter(result.source().toDate()))throw error("STATEMENT_CONFLICT_INVALID");
   if(p.get("state").equals("REFUNDED")){if(result.rows().stream().anyMatch(r->r.source().type()==Type.PAYOUT&&(Objects.equals(r.paymentId(),input.relatedId())||r.source().paymentReference().equals(order.reference()))))throw error("STATEMENT_CONFLICT_INVALID");if(result.blockers().stream().anyMatch(x->!x.equals("PAYMENT_CONFLICT")))throw error("STATEMENT_NOT_RECONCILED");}
   else if(p.get("state").equals("REFUND_PENDING")){
    if(result.rows().stream().anyMatch(r->r.source().type()==Type.PAYOUT&&r.source().paymentReference().equals(order.reference()))||!result.rows().stream().allMatch(r->r.status().equals("RESOLVED"))||!result.balances().get("openingDifference").equals("0")||!result.balances().get("pendingAccounting").equals("1")||new BigDecimal(result.balances().get("closingDifference")).compareTo(new BigDecimal(order.amount()).negate())!=0||!result.missingPayments().equals(List.of(input.relatedId()))||!result.unmatchedCbs().equals(List.of(input.relatedId().toString())))throw error("STATEMENT_NOT_RECONCILED");
   }
   else if(List.of("RETURN_PENDING","RETURNED").contains(p.get("state"))){if(result.rows().stream().noneMatch(r->"RETURN".equals(r.decisionKind())&&Objects.equals(r.journalId(),p.get("return_id"))&&r.source().type()==Type.REVERSAL&&r.source().paymentReference().equals(order.reference())&&money(r.source().credit()).compareTo(new BigDecimal(order.amount()))==0))throw error("STATEMENT_CONFLICT_INVALID");}
   else if(p.get("state").equals("SETTLED")){if(result.rows().stream().noneMatch(r->r.source().type()==Type.PAYOUT&&fits(r.source(),p)&&receiptMatches(bank.id(),input.relatedId(),r.source().receipt())))throw error("STATEMENT_CONFLICT_INVALID");}
   else throw error("STATEMENT_CONFLICT_INVALID");return result;
  }
  var row=selected(result,input.lineId());if(input.kind()!=Kind.REVERSE&&input.kind()!=Kind.UNLINK&&row.decisionId()!=null&&!List.of("REVERSE","UNLINK").contains(row.decisionKind()))throw error("STATEMENT_LINE_RESOLVED");if(row.status().equals("POSTING_PENDING"))throw error("PAYMENT_POSTING_REQUIRED");
  if(List.of(Kind.MATCH,Kind.RETURN,Kind.LINK,Kind.BOOK).contains(input.kind())&&jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_line l JOIN platform.statement_import b ON b.id=l.batch_id WHERE b.tenant_id=? AND b.ledger_id=? AND l.id<>? AND l.source->>'receipt'=? AND l.source->>'type'=? AND EXISTS(SELECT 1 FROM platform.statement_decision d WHERE d.line_id=l.id AND d.kind IN ('MATCH','LINK','BOOK','RETURN')))",Boolean.class,bank.id(),result.source().ledgerId(),row.id(),row.source().receipt(),row.source().type().name()))throw error("STATEMENT_RECEIPT_USED");
  if(input.kind()==Kind.MATCH){var p=payment(actor,bank.id(),candidate(row,input));var order=paymentOrder(p);if(row.source().type()!=Type.PAYOUT||!order.settlementLedgerId().equals(result.source().ledgerId())||!fits(row.source(),p)||Boolean.TRUE.equals(p.get("reconciliation_conflict"))||!List.of("SUBMITTED","UNKNOWN","SETTLED","RETURN_PENDING","RETURNED").contains(p.get("state")))throw error("PAYMENT_RECONCILIATION_MISMATCH");if(List.of("SETTLED","RETURN_PENDING","RETURNED").contains(p.get("state"))&&!receiptMatches(bank.id(),candidate(row,input),row.source().receipt()))throw error("PAYMENT_RECEIPT_USED");}
  else if(input.kind()==Kind.RETURN){returns.validate(actor,bank,input.relatedId(),input.batchId(),row.id());}
  else if(input.kind()==Kind.BOOK){if(row.source().type()==Type.REVERSAL&&jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.payment_order WHERE tenant_id=? AND payload->>'reference'=?)",Boolean.class,bank.id(),row.source().paymentReference()))throw error("PAYMENT_RETURN_REQUIRED");if(row.source().type()==Type.PAYOUT&&!row.status().equals("UNMATCHED_EXTERNAL")&&!"REVERSE".equals(row.decisionKind()))throw error("STATEMENT_USE_PAYMENT_MATCH");var contra=ledger(bank.id(),input.relatedId());if(row.source().type()==Type.FEE&&!contra.get("category").equals("EXPENSE"))throw error("STATEMENT_FEE_LEDGER_INVALID");journals.validateStatement(bank,adjustment(actor,bank,result,row,input));}
  else if(input.kind()==Kind.LINK){validateLink(actor,bank,result,row,input.relatedId());}
  else if(input.kind()==Kind.UNLINK){if(!"LINK".equals(row.decisionKind()))throw error("STATEMENT_ACTION_INVALID");}
  else if(input.kind()==Kind.REVERSE){if(!"BOOK".equals(row.decisionKind())||row.journalId()==null||!row.status().equals("RESOLVED"))throw error("STATEMENT_REVERSAL_INVALID");journals.validateStatement(bank,adjustment(actor,bank,result,row,input));}
  else if(input.kind()==Kind.DUPLICATE){if(!jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_line a JOIN platform.statement_line b ON b.identity_hash=a.identity_hash JOIN platform.statement_import x ON x.id=b.batch_id JOIN platform.statement_import y ON y.id=a.batch_id WHERE a.id=? AND b.id=? AND x.tenant_id=y.tenant_id AND x.ledger_id=y.ledger_id AND x.status='CLOSED' AND EXISTS(SELECT 1 FROM platform.statement_decision d WHERE d.id=b.decision_id AND d.kind<>'DUPLICATE') AND x.id<>y.id)",Boolean.class,row.id(),input.relatedId()))throw error("STATEMENT_DUPLICATE_INVALID");}
  return result;
 }
 private void validateLink(Actor actor,Tenant bank,Report report,Row row,UUID journalId){
  if(row.source().type()==Type.PAYOUT)throw error("STATEMENT_USE_PAYMENT_MATCH");var j=journals.postedForReconciliation(actor,bank.id(),journalId);var walletLines=j.lines().stream().filter(l->l.ledgerId().equals(report.source().ledgerId())).toList();if(walletLines.size()!=1||!j.businessDate().equals(row.source().date())||!j.currency().equals("KES"))throw error("STATEMENT_JOURNAL_MISMATCH");var line=walletLines.getFirst();var delta=new BigDecimal(line.amount()).multiply(line.side()==JournalModels.Side.DEBIT?BigDecimal.ONE:BigDecimal.ONE.negate());if(delta.compareTo(money(row.source().credit()).subtract(money(row.source().debit())))!=0)throw error("STATEMENT_JOURNAL_MISMATCH");
  if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_journal_claim WHERE tenant_id=? AND ledger_id=? AND journal_id=? AND line_id<>?) OR EXISTS(SELECT 1 FROM platform.journal_delivery WHERE reversal_of=?)",Boolean.class,bank.id(),report.source().ledgerId(),journalId,row.id(),journalId))throw error("STATEMENT_JOURNAL_USED");
 }
 private JournalModels.Change adjustment(Actor actor,Tenant bank,Report report,Row row,Action input){
  var date=reference.read(bank).businessDate();if(date.isBefore(report.source().fromDate())||date.isAfter(report.source().toDate()))throw error("STATEMENT_POSTING_PERIOD");var asset=ledger(bank.id(),report.source().ledgerId());List<JournalModels.Line> lines;UUID reversal=null;
  if(input.kind()==Kind.REVERSE){var old=journals.postedForReconciliation(actor,bank.id(),row.journalId());lines=old.lines().stream().map(l->new JournalModels.Line(l.ledgerId(),l.side()==JournalModels.Side.DEBIT?JournalModels.Side.CREDIT:JournalModels.Side.DEBIT,l.amount())).toList();reversal=old.id();}
  else{boolean credit=money(row.source().credit()).signum()>0;String amount=credit?row.source().credit():row.source().debit();lines=List.of(new JournalModels.Line(report.source().ledgerId(),credit?JournalModels.Side.DEBIT:JournalModels.Side.CREDIT,amount),new JournalModels.Line(input.relatedId(),credit?JournalModels.Side.CREDIT:JournalModels.Side.DEBIT,amount));}
  return new JournalModels.Change(input.expectedVersion(),"STMT-"+input.kind()+"-"+row.id()+"-"+input.expectedVersion(),input.reason(),date,(UUID)asset.get("legal_entity_id"),"KES",lines,reversal,input.reason());
 }
 public Map<String,Object> values(Actor actor,Tenant bank,Action input){var report=validate(actor,bank,input);var values=new LinkedHashMap<String,Object>();values.put("action",input);values.put("statement",report.source());values.put("balances",report.balances());values.put("blockers",report.blockers());if(input.lineId()!=null)values.put("line",selected(report,input.lineId()));if(input.kind()==Kind.BOOK||input.kind()==Kind.REVERSE)values.put("journal",journals.values(bank.id(),adjustment(actor,bank,report,selected(report,input.lineId()),input)));if(input.kind()==Kind.RETURN)values.put("customerCredit",returns.change(bank,input.relatedId(),bank.version()));return values;}
 public void apply(Actor actor,UUID bankId,Action input,UUID approvalId,String maker){
  PaymentAccess.require(jdbc,actor,bankId,PaymentAccess.Capability.APPROVE);var bank=tenants.get(bankId,true);var report=validate(actor,bank,input);var batch=batch(actor,bankId,input.batchId());if(actor.subject().equals(batch.get("importer")))throw error("STATEMENT_INDEPENDENT_REVIEW_REQUIRED");UUID journalId=null,related=input.relatedId();
  Row row=input.lineId()==null?null:selected(report,input.lineId());
  if(input.kind()==Kind.MATCH){related=candidate(row,input);var p=payment(actor,bankId,related);if(!List.of("SETTLED","RETURN_PENDING","RETURNED").contains(p.get("state"))){
    var s=new PaymentModels.Statement(input.expectedVersion(),related,row.source().receipt(),text(money(row.source().debit())),"KES",row.source().beneficiary(),PaymentModels.Outcome.PAID,row.source().date(),input.evidenceReference(),input.reason());UUID statementId=UUID.randomUUID();jdbc.update("INSERT INTO platform.payment_statement(id,tenant_id,payment_id,issuer,subject,idempotency_key,payload) VALUES (?,?,?,?,?,?,?::jsonb)",statementId,bankId,related,actor.issuer(),batch.get("importer"),approvalId,JSON.writeValueAsString(s));payments.reconcile(actor,bankId,new PaymentModels.Reconcile(input.expectedVersion(),related,PaymentModels.Resolution.MATCH,statementId,input.reason()),approvalId,maker);
   }}
  else if(input.kind()==Kind.RETURN){returns.apply(actor,bank,related,input.batchId(),row.id(),approvalId,maker);journalId=approvalId;}
  else if(input.kind()==Kind.BOOK||input.kind()==Kind.REVERSE){journals.enqueueStatement(actor,bankId,adjustment(actor,bank,report,row,input),approvalId,maker);journalId=approvalId;}
  else if(input.kind()==Kind.LINK)journalId=input.relatedId();
  else if(input.kind()==Kind.CLOSE||input.kind()==Kind.REOPEN||input.kind()==Kind.SUPERSEDE)jdbc.update("UPDATE platform.statement_import SET status=?,status_decision_id=? WHERE id=?",input.kind()==Kind.CLOSE?"CLOSED":input.kind()==Kind.REOPEN?"OPEN":"SUPERSEDED",approvalId,input.batchId());
  else if(input.kind()==Kind.CLEAR_CONFLICT){jdbc.update("UPDATE platform.payment_order SET reconciliation_conflict=false WHERE tenant_id=? AND id=?",bankId,input.relatedId());jdbc.update("INSERT INTO platform.payment_event VALUES (?,?,?,?,?,?::jsonb,clock_timestamp())",UUID.randomUUID(),bankId,input.relatedId(),"STATEMENT_CONFLICT_REVIEW",actor.subject(),JSON.writeValueAsString(Map.of("approvalId",approvalId,"batchId",input.batchId(),"evidenceReference",input.evidenceReference(),"reason",input.reason())));}
  jdbc.update("INSERT INTO platform.statement_decision(id,tenant_id,batch_id,line_id,kind,related_id,journal_id,subject,payload) VALUES (?,?,?,?,?,?,?,?,?::jsonb)",approvalId,bankId,input.batchId(),input.lineId(),input.kind().name(),related,journalId,actor.subject(),JSON.writeValueAsString(Map.of("action",input,"report",report)));
  if(row!=null)jdbc.update("UPDATE platform.statement_line SET decision_id=? WHERE id=?",approvalId,row.id());
  if(journalId!=null)jdbc.update("INSERT INTO platform.statement_journal_claim VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING",bankId,report.source().ledgerId(),journalId,row.id(),approvalId);
  changed(actor,tenants.get(bankId,false),"STATEMENT_"+input.kind(),input.batchId());
 }
 public Map<String,String> export(Actor actor,UUID bank,UUID id){PaymentAccess.require(jdbc,actor,bank,PaymentAccess.Capability.READ);return tx.execute(t->{var tenant=tenants.get(bank,true);var report=report(actor,tenant,id);var csv=new StringBuilder();csv.append("Section,Key,Value\r\n");csv.append(csvRow("Statement","Reference",report.source().statementReference()));csv.append(csvRow("Statement","Wallet",report.source().walletReference()));csv.append(csvRow("Statement","Status",report.status()));csv.append(csvRow("Statement","Report hash",report.reportHash()));report.balances().forEach((k,v)->csv.append(csvRow("Balance",k,v)));for(String blocker:report.blockers())csv.append(csvRow("Blocker",blocker,""));for(String journal:report.unmatchedCbs())csv.append(csvRow("Unmatched CBS",journal,""));for(UUID payment:report.missingPayments())csv.append(csvRow("Missing provider",payment.toString(),""));for(UUID payment:report.conflicts())csv.append(csvRow("Conflict",payment.toString(),""));csv.append("\r\nRow ID,Receipt,Date,Type,Credit,Debit,Balance,CBS reference,Beneficiary,Status,Decision,Payment ID,Journal ID\r\n");for(var row:report.rows()){var l=row.source();csv.append(csvRow(row.id().toString(),l.receipt(),l.date().toString(),l.type().name(),l.credit(),l.debit(),l.balance(),l.paymentReference(),l.beneficiary(),row.status(),Objects.toString(row.decisionKind(),""),Objects.toString(row.paymentId(),""),Objects.toString(row.journalId(),"")));}tenants.audit(actor,bank,"STATEMENT_EXPORTED",tenant.version(),tenant.status(),tenant.status(),"Statement export",null,null,Map.of("batchId",id,"reportHash",report.reportHash()));return Map.of("csv",csv.toString());});}
 private static String csvRow(String...cells){return Arrays.stream(cells).map(v->{String safe=v.matches("^[=+@\\-\\t\\r\\n].*")?"'"+v:v;return "\""+safe.replace("\"","\"\"")+"\"";}).collect(Collectors.joining(","))+"\r\n";}
 public static void requireWritable(JdbcTemplate jdbc,UUID bank,UUID ledger,LocalDate date){if(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM platform.statement_import WHERE tenant_id=? AND ledger_id=? AND status='CLOSED' AND (source->>'fromDate')::date<=? AND (source->>'toDate')::date>=?)",Boolean.class,bank,ledger,date,date))throw error("STATEMENT_PERIOD_CLOSED");}
 private void changed(Actor actor,Tenant bank,String action,UUID id){tenants.change(bank,bank.status(),bank.displayName(),bank.defaultLanguage());tenants.audit(actor,bank.id(),action,bank.version()+1,bank.status(),bank.status(),"Statement "+id,null,null,Map.of("batchId",id));}
 private static TenantException error(String code){return new TenantException(409,code,"Statement reconciliation requires attention");}
}
